effect.shader:
void main() {
    vec2 p = acScreenNorm - center;
    p.x *= acAspect;
    float r = pow(length(p) / 0.7071, power);
    vec2 dir = normalize(p + vec2(1e-6));
    dir.x /= acAspect;
    vec2 off = dir * amount * r;

    float rr = texture(inputImg, acScreenNorm + off).r;
    float gg = texture(inputImg, acScreenNorm).g;
    float bb = texture(inputImg, acScreenNorm - off).b;
    float aa = texture(inputImg, acScreenNorm).a;
    fragColor = vec4(rr, gg, bb, aa);
}
